// tb_trace_replay
//
// Phase 23's trace-replay testbench, RTL-side half (fpga_docs/bugs.md
// #11): reads trace.csv (generated by
// host/fpga_bridge/tools/gen_trace.cpp - same 1,000,000-order workload
// as every other benchmark in this project, run through the golden
// BoundedMatchingEngine C++ reference), drives bounded_order_book
// directly at the real, non-overridden N_LEVELS=16/M_ORDERS=8 defaults
// with the identical inputs, and compares actual vs. expected order by
// order. Stops at the FIRST mismatch and prints full context - built
// specifically to root-cause the real, reproducible 53.275% (hardware)
// vs. 72.4% (C++ reference) reject-rate gap that hardware
// experimentation alone couldn't pin down further (see bugs.md #11's
// full trail: multi-level walk logic and per-order bounds both already
// confirmed correct by tb_bounded_order_book_multilevel.sv and the
// fpga_bridge_debug.cpp per-order scan).
`timescale 1ns/1ps

module tb_trace_replay;

    localparam int N_LEVELS = 16; // real defaults, matching the C++ reference's <16,8>
    localparam int M_ORDERS = 8;
    localparam int PRICE_W  = 32;
    localparam int QTY_W    = 32;
    localparam int ID_W     = 64;

    logic clk = 0;
    logic rst_n = 0;

    logic                       start_pulse;
    logic [ID_W-1:0]            in_order_id;
    logic                        in_side;
    logic signed [PRICE_W-1:0]  in_price;
    logic [QTY_W-1:0]           in_qty;

    logic                       busy;
    logic                       done_pulse;
    logic [QTY_W-1:0]           out_trade_qty;
    logic signed [PRICE_W-1:0] out_trade_price;
    logic [ID_W-1:0]            out_trade_id;
    logic                        out_rejected;
    logic [31:0]                 out_latency_cycles;

    always #5 clk = ~clk;

    bounded_order_book #(
        .N_LEVELS (N_LEVELS),
        .M_ORDERS (M_ORDERS),
        .PRICE_W  (PRICE_W),
        .QTY_W    (QTY_W),
        .ID_W     (ID_W)
    ) dut (
        .clk                 (clk),
        .rst_n               (rst_n),
        .start_pulse         (start_pulse),
        .in_order_id         (in_order_id),
        .in_side             (in_side),
        .in_price            (in_price),
        .in_qty              (in_qty),
        .busy                (busy),
        .done_pulse          (done_pulse),
        .out_trade_qty       (out_trade_qty),
        .out_trade_price     (out_trade_price),
        .out_trade_id        (out_trade_id),
        .out_rejected        (out_rejected),
        .out_latency_cycles  (out_latency_cycles)
    );

    task automatic reset_dut();
        rst_n = 0;
        start_pulse = 0;
        in_order_id = '0;
        in_side = 0;
        in_price = '0;
        in_qty = '0;
        repeat (4) @(negedge clk);
        rst_n = 1;
        repeat (4) @(negedge clk);
    endtask

    task automatic submit_and_wait(
        input logic [63:0]        order_id,
        input logic                side,
        input logic signed [31:0] price,
        input logic [31:0]        qty
    );
        int timeout;
        @(negedge clk);
        in_order_id = order_id;
        in_side     = side;
        in_price    = price;
        in_qty      = qty;
        start_pulse = 1'b1;
        @(negedge clk);
        start_pulse = 1'b0;
        timeout = 0;
        while (!done_pulse && timeout < 1000) begin
            @(negedge clk);
            timeout++;
        end
        if (timeout >= 1000) begin
            $display("[TIMEOUT] order_id=%0d never saw done_pulse", order_id);
        end
    endtask

    int fd;
    int r;
    longint unsigned order_id;
    int side_i;
    int price_i;
    int qty_i;
    int exp_rejected_i;
    int unsigned exp_trade_qty;
    int exp_trade_price;
    longint unsigned exp_trade_id;

    longint checked;
    longint mismatches;
    string line;

    initial begin
        checked = 0;
        mismatches = 0;

        fd = $fopen("trace.csv", "r");
        if (fd == 0) begin
            $display("[ERROR] could not open trace.csv - run gen_trace first and copy it into sim/");
            $finish;
        end
        r = $fgets(line, fd); // skip header

        reset_dut();

        while (!$feof(fd) && mismatches == 0) begin
            r = $fscanf(fd, "%d,%d,%d,%d,%d,%d,%d,%d\n", order_id, side_i, price_i, qty_i,
                        exp_rejected_i, exp_trade_qty, exp_trade_price, exp_trade_id);
            if (r != 8) begin
                // trailing blank line or EOF artifact - stop cleanly
                if (!$feof(fd))
                    $display("[WARN] short read (r=%0d) at checked=%0d, stopping", r, checked);
                break;
            end

            submit_and_wait(order_id, side_i[0], price_i, qty_i);
            checked++;

            if (out_rejected !== exp_rejected_i[0] || out_trade_qty !== exp_trade_qty
                || out_trade_price !== exp_trade_price || out_trade_id !== exp_trade_id) begin
                mismatches++;
                $display("========================================================");
                $display("[MISMATCH] at order #%0d (order_id=%0d) after %0d clean matches",
                          checked, order_id, checked - 1);
                $display("  input:    side=%0d price=%0d qty=%0d", side_i, price_i, qty_i);
                $display("  RTL:      rejected=%0b trade_qty=%0d trade_price=%0d trade_id=%0d",
                          out_rejected, out_trade_qty, out_trade_price, out_trade_id);
                $display("  C++ ref:  rejected=%0d trade_qty=%0d trade_price=%0d trade_id=%0d",
                          exp_rejected_i, exp_trade_qty, exp_trade_price, exp_trade_id);
                $display("========================================================");
            end

            if (checked % 100000 == 0)
                $display("... %0d orders checked, %0d mismatches so far", checked, mismatches);
        end

        $fclose(fd);

        if (mismatches == 0)
            $display("ALL %0d ORDERS MATCHED THE C++ REFERENCE EXACTLY", checked);
        else
            $display("STOPPED after first mismatch: %0d orders checked, %0d mismatch(es)", checked, mismatches);

        $finish;
    end

endmodule
